(function(){'use strict';
var catalog={'weight-gain':{name:'Weight Gain',image:'weight-gain-square.jpg'},'weight-loss':{name:'Weight Loss',image:'weight-loss-square.jpg'},'nutrition-guide':{name:'Nutrition Guide',image:'nutrition-chef.jpg'}};
var cart={};try{cart=JSON.parse(localStorage.getItem('fit-demo-cart')||'{}')}catch(e){}if(!cart||typeof cart!=='object'||Array.isArray(cart))cart={};
Object.keys(cart).forEach(function(k){if(!Object.prototype.hasOwnProperty.call(catalog,k)||!Number.isInteger(cart[k])||cart[k]<1)delete cart[k];else cart[k]=Math.min(10,cart[k]);});
var coursePrice=135200;
function money(n){return new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(n)}
function save(){try{localStorage.setItem('fit-demo-cart',JSON.stringify(cart))}catch(e){}render()}
function render(){var keys=Object.keys(cart),total=keys.reduce(function(n,k){return n+cart[k]*coursePrice},0);document.querySelectorAll('[data-cart-count]').forEach(function(n){n.textContent=keys.reduce(function(n,k){return n+cart[k]},0)});document.querySelectorAll('[data-cart-total]').forEach(function(n){n.textContent=money(total)});
var table=document.getElementById('fit-cart-table');if(table){table.innerHTML=keys.length?'<div class="fit-table-scroll"><table class="shop_table shop_table_responsive cart"><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Total</th><th>Remove</th></tr></thead><tbody>'+keys.map(function(k){return '<tr><td><a href="'+k+'.html"><img class="fit-cart-thumb" src="images/fitislit/'+catalog[k].image+'" alt="">'+catalog[k].name+'</a></td><td>'+money(coursePrice)+'</td><td><input aria-label="Quantity for '+catalog[k].name+'" type="number" min="1" max="10" step="1" value="'+cart[k]+'" data-quantity="'+k+'"></td><td>'+money(cart[k]*coursePrice)+'</td><td><button type="button" data-remove="'+k+'" aria-label="Remove '+catalog[k].name+'">×</button></td></tr>'}).join('')+'</tbody></table></div>':'<p>Your cart is empty.</p>';document.getElementById('fit-checkout-link').hidden=!keys.length;}
var order=document.getElementById('fit-order-table');if(order){order.innerHTML='<table class="shop_table"><thead><tr><th>Product</th><th>Total</th></tr></thead><tbody>'+keys.map(function(k){return '<tr><td>'+catalog[k].name+' × '+cart[k]+'</td><td>'+money(cart[k]*coursePrice)+'</td></tr>'}).join('')+'</tbody><tfoot><tr><th>Total (NGN)</th><td>'+money(total)+'</td></tr></tfoot></table>';document.getElementById('fit-order-form').hidden=!keys.length;document.getElementById('fit-checkout-empty').hidden=!!keys.length;}}
var direct=new URLSearchParams(location.search).get('product');if(document.getElementById('fit-order-form')&&Object.prototype.hasOwnProperty.call(catalog,direct)){cart[direct]=cart[direct]||1;save();}
document.querySelectorAll('.fit-add-form').forEach(function(form){form.addEventListener('submit',function(e){e.preventDefault();if(!form.reportValidity())return;var key=form.dataset.product,qty=Number(form.elements.quantity.value);if(!Object.prototype.hasOwnProperty.call(catalog,key)||!Number.isInteger(qty)||qty<1||qty>10)return;cart[key]=Math.min(10,(cart[key]||0)+qty);save();form.parentElement.querySelector('.fit-cart-status').innerHTML='Added to your demo cart. <a href="cart.html">View cart</a>';});});
document.addEventListener('click',function(e){var b=e.target.closest('[data-remove]');if(b){delete cart[b.dataset.remove];save();}});
document.addEventListener('change',function(e){var k=e.target.dataset.quantity;if(k&&Object.prototype.hasOwnProperty.call(cart,k)){var q=Number(e.target.value);if(Number.isInteger(q)&&q>=1&&q<=10){cart[k]=q;save()}else e.target.value=cart[k];}});
var form=document.getElementById('fit-order-form');if(form)form.addEventListener('submit',function(e){e.preventDefault();if(!Object.keys(cart).length)return;cart={};save();form.hidden=true;document.getElementById('fit-checkout-empty').hidden=true;var result=document.getElementById('fit-order-success');result.hidden=false;result.focus();});render();
})();
